<?php
declare(strict_types=1); require_once __DIR__ . '/security.php'; require_once __DIR__ . '/db.php'; require_login();$q=db()->prepare('SELECT p.* FROM wishlist w JOIN products p ON p.id=w.product_id WHERE w.user_id=? AND p.is_active=1 ORDER BY w.created_at DESC');$q->execute([$_SESSION['user_id']]);$products=$q->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Wishlist</title><link rel="stylesheet" href="style.css"><script src="app.js" defer></script></head><body><header class="site-header"><a class="brand" href="index.php">Sanderi <span>Stationary</span></a><nav class="nav"><a href="products.php">Shop</a><a href="cart.php">Cart</a><a href="profile.php">Profile</a></nav></header><main class="page-shell"><div class="eyebrow">Saved for later</div><h1>Wishlist</h1><div class="product-grid"><?php foreach($products as $product): ?><article class="product-card"><div class="product-body"><h2><?= htmlspecialchars($product['name']) ?></h2><p>₹<?= number_format((float)$product['price'],2) ?></p><a class="button" href="product.php?id=<?= $product['id'] ?>">View product</a></div></article><?php endforeach; ?></div><?php if(!$products): ?><p>Your wishlist is empty.</p><?php endif; ?></main></body></html>
